form.script:
var MAX_DELIVERY_STOPS = 20;
var stopCounter = 1; // starts at 1, Stop 1 already rendered
var stopKeyCounter = 0;
document.querySelectorAll('.delivery-stop-row').forEach(function(row) {
    var match = (row.dataset.stopKey || '').match(/^DL(\d+)$/);
    if (match) stopKeyCounter = Math.max(stopKeyCounter, parseInt(match[1], 10));
});

// Template for a new stop row (cloned from Stop 1 style)
function createStopRow(index) {
    var tmpl = document.querySelector('.delivery-stop-row');
    if (!tmpl) return null;
    var row = tmpl.cloneNode(true);
    row.setAttribute('data-stop-index', index);
    stopKeyCounter += 1;
    row.setAttribute('data-stop-key', 'DL' + stopKeyCounter);
    row.querySelector('.stop-label').textContent = 'Delivery Stop ' + (index + 1);
    // Update select name
    var sel = row.querySelector('select');
    sel.name = 'delivery_saved_location_id_' + (index + 1);
    sel.value = '';
    sel.classList.remove('is-valid');
    var keyInput = row.querySelector('.delivery-stop-key');
    if (keyInput) { keyInput.name = 'delivery_stop_key_' + (index + 1); keyInput.value = row.dataset.stopKey; }
    // Clear detail text
    row.querySelector('.stop-detail-text').textContent = '';
    // Update add-loc link
    var addLoc = row.querySelector('.add-loc-link');
    if (addLoc) addLoc.href = '/my/saved-locations/add?type=delivery&return=booking';
    // Show all buttons (hidden on template)
    row.querySelector('.move-up-btn').style.display = '';
    row.querySelector('.move-down-btn').style.display = '';
    row.querySelector('.remove-stop-btn').style.display = '';
    return row;
}

function rebindStopRow(row, index, total) {
    // Label
    row.querySelector('.stop-label').textContent = 'Delivery Stop ' + (index + 1);
    // Select name
    var sel = row.querySelector('select');
    sel.name = 'delivery_saved_location_id_' + (index + 1);
    var keyInput = row.querySelector('.delivery-stop-key');
    if (keyInput) {
        if (!row.dataset.stopKey) row.dataset.stopKey = keyInput.value || ('DL' + (index + 1));
        keyInput.name = 'delivery_stop_key_' + (index + 1);
        keyInput.value = row.dataset.stopKey;
    }
    // Add-loc link
    var addLoc = row.querySelector('.add-loc-link');
    if (addLoc) addLoc.href = '/my/saved-locations/add?type=delivery&return=booking';
    // Move up: hide for first
    row.querySelector('.move-up-btn').style.display = (index > 0) ? '' : 'none';
    // Move down: hide for last
    row.querySelector('.move-down-btn').style.display = (index < total - 1) ? '' : 'none';
    // Remove: show for all but stop 0 when total > 1
    row.querySelector('.remove-stop-btn').style.display = (total > 1) ? '' : 'none';
    // Bind select change
    bindSelectDetail(row);
}

function bindSelectDetail(row) {
    var sel = row.querySelector('select');
    var detail = row.querySelector('.stop-detail-text');
    if (!sel || !detail) return;
    sel.addEventListener('change', function() {
        var opt = sel.options[sel.selectedIndex];
        if (opt && opt.value) {
            var street = opt.getAttribute('data-street') || '';
            var city = opt.getAttribute('data-city') || '';
            detail.innerHTML = 'Selected: <strong>' + opt.text.replace(/ ★ \(Default\)/, '') + '</strong>' +
                (street ? ' — ' + street + (city ? ', ' + city : '') : '');
        } else {
            detail.textContent = '';
        }
    });
}

function refreshAllStops() {
    var rows = document.querySelectorAll('.delivery-stop-row');
    var total = rows.length;
    stopCounter = total;
    rows.forEach(function(row, i) {
        row.setAttribute('data-stop-index', i);
        rebindStopRow(row, i, total);
    });
    document.getElementById('max_stops_msg').style.display = (total >= MAX_DELIVERY_STOPS) ? '' : 'none';
    document.getElementById('add_delivery_stop_btn').style.display = (total >= MAX_DELIVERY_STOPS) ? 'none' : '';
}

document.getElementById('add_delivery_stop_btn').addEventListener('click', function(e) {
    e.preventDefault();
    var rows = document.querySelectorAll('.delivery-stop-row');
    if (rows.length >= MAX_DELIVERY_STOPS) return;
    var newRow = createStopRow(rows.length);
    if (newRow) {
        document.getElementById('delivery_stops_container').insertBefore(
            newRow, document.getElementById('max_stops_msg')
        );
        refreshAllStops();
    }
});

// Delegate clicks for move/remove buttons
document.getElementById('delivery_stops_container').addEventListener('click', function(e) {
    var btn = e.target.closest('button');
    if (!btn) return;
    var row = btn.closest('.delivery-stop-row');
    if (!row) return;

    if (btn.classList.contains('move-up-btn')) {
        var prev = row.previousElementSibling;
        if (prev && prev.classList.contains('delivery-stop-row')) {
            row.parentNode.insertBefore(row, prev);
            refreshAllStops();
        }
    } else if (btn.classList.contains('move-down-btn')) {
        var next = row.nextElementSibling;
        if (next && next.classList.contains('delivery-stop-row')) {
            row.parentNode.insertBefore(next, row);
            refreshAllStops();
        }
    } else if (btn.classList.contains('remove-stop-btn')) {
        var rows = document.querySelectorAll('.delivery-stop-row');
        if (rows.length <= 1) return;
        row.remove();
        refreshAllStops();
    }
});

// Initialize Stop 1
document.addEventListener('DOMContentLoaded', function() {
    bindSelectDetail(document.querySelector('.delivery-stop-row'));
    refreshAllStops();
    // Bind pickup detail
    var puSel = document.querySelector('select[name="pickup_saved_location_id"]');
    var puDetail = document.getElementById('pickup_detail_text');
    if (puSel && puDetail) {
        function refreshPu() {
            var opt = puSel.options[puSel.selectedIndex];
            if (opt && opt.value) {
                puDetail.innerHTML = 'Selected: <strong>' + opt.text.replace(/ ★ \(Default\)/, '') + '</strong>';
            } else {
                puDetail.innerHTML = '';
            }
        }
        puSel.addEventListener('change', refreshPu);
        refreshPu();
    }
});

document.addEventListener('DOMContentLoaded', function() {
    var MAX_PICKUP_STOPS = 20;
    var container = document.getElementById('pickup_stops_container');
    var add = document.getElementById('add_pickup_stop_btn');
    if (!container || !add) return;
    var pickupKeyCounter = 0;
    container.querySelectorAll('.pickup-stop-row').forEach(function(row) {
        var match = (row.dataset.stopKey || '').match(/^PU(\d+)$/);
        if (match) pickupKeyCounter = Math.max(pickupKeyCounter, parseInt(match[1], 10));
    });
    function bind(row) {
        var sel = row.querySelector('.pickup-select');
        var detail = row.querySelector('.stop-detail-text');
        if (!sel || !detail) return;
        sel.addEventListener('change', function() {
            var opt = sel.options[sel.selectedIndex];
            if (opt && opt.value) {
                detail.innerHTML = 'Selected: <strong>' + opt.text.replace(/ ★ \(Default\)/, '') + '</strong>';
            } else detail.textContent = '';
        });
        sel.dispatchEvent(new Event('change'));
    }
    function rebind() {
        var rows = container.querySelectorAll('.pickup-stop-row');
        rows.forEach(function(row, i) {
            row.dataset.stopIndex = i;
            row.querySelector('.stop-label').textContent = 'Pickup Stop ' + (i + 1);
            var sel = row.querySelector('.pickup-select');
            if (sel) sel.name = 'pickup_saved_location_id_' + (i + 1);
            var key = row.querySelector('.pickup-stop-key');
            if (key) {
                key.name = 'pickup_stop_key_' + (i + 1);
                key.value = row.dataset.stopKey || ('PU' + (i + 1));
                row.dataset.stopKey = key.value;
            }
            var up = row.querySelector('.move-up-btn');
            var down = row.querySelector('.move-down-btn');
            var remove = row.querySelector('.remove-stop-btn');
            if (up) up.style.display = i ? '' : 'none';
            if (down) down.style.display = i < rows.length - 1 ? '' : 'none';
            if (remove) remove.style.display = rows.length > 1 ? '' : 'none';
            bind(row);
        });
        document.getElementById('max_pickup_stops_msg').style.display = rows.length >= MAX_PICKUP_STOPS ? '' : 'none';
        add.style.display = rows.length >= MAX_PICKUP_STOPS ? 'none' : '';
    }
    add.addEventListener('click', function() {
        var rows = container.querySelectorAll('.pickup-stop-row');
        if (rows.length >= MAX_PICKUP_STOPS) return;
    var row = rows[0].cloneNode(true);
    var key;
    do { pickupKeyCounter += 1; key = 'PU' + pickupKeyCounter; }
    while (container.querySelector('[data-stop-key="' + key + '"]'));
        row.dataset.stopKey = key;
        row.querySelector('.pickup-select').value = '';
        row.querySelector('.pickup-stop-key').value = key;
        row.querySelector('.stop-detail-text').textContent = '';
        container.insertBefore(row, document.getElementById('max_pickup_stops_msg'));
        rebind();
    });
    container.addEventListener('click', function(e) {
        var btn = e.target.closest('button');
        var row = btn && btn.closest('.pickup-stop-row');
        if (!row) return;
        var rows = Array.from(container.querySelectorAll('.pickup-stop-row'));
        if (btn.classList.contains('move-up-btn')) {
            var i = rows.indexOf(row); if (i > 0) container.insertBefore(row, rows[i - 1]);
        } else if (btn.classList.contains('move-down-btn')) {
            var j = rows.indexOf(row); if (j < rows.length - 1) container.insertBefore(rows[j + 1], row);
        } else if (btn.classList.contains('remove-stop-btn') && rows.length > 1) row.remove();
        rebind();
    });
    rebind();
});

div.script:
document.addEventListener('DOMContentLoaded', function() {
    // Auto-select the only real option in each dropdown
    // when nothing is pre-selected (no default flag set)
    ['pickup_saved_location_id_1', 'delivery_saved_location_id_1'].forEach(function(name) {
        var sel = document.querySelector('select[name="' + name + '"]');
        if (!sel) return;
        // Count real options (value != "")
        var realOpts = Array.from(sel.options).filter(function(o) { return o.value !== ''; });
        if (realOpts.length === 1 && sel.value === '') {
            sel.value = realOpts[0].value;
        }
    });
});

t.script:
document.addEventListener('DOMContentLoaded', function() {
    var newId = '<t t-esc="new_loc_id"/>';
    var newType = '<t t-esc="new_loc_type"/>';
    var targetKey = new URLSearchParams(window.location.search).get('return_stop_key') || '';
    document.querySelectorAll('.pickup-stop-row, .delivery-stop-row').forEach(function(row) {
        var key = (row.dataset.stopKey || (row.querySelector('.pickup-stop-key, .delivery-stop-key') || {}).value || '');
        var isPickup = row.classList.contains('pickup-stop-row');
        if (key !== targetKey || (isPickup && newType !== 'pickup' && newType !== 'both') ||
            (!isPickup && newType !== 'delivery' && newType !== 'both')) return;
        var select = row.querySelector('select');
        if (select) { select.value = newId; select.dispatchEvent(new Event('change')); }
    });
});

div.script:
document.addEventListener('DOMContentLoaded', function() {
    var form = document.querySelector('form[action="/my/booking/new"]');
    if (!form) return;
    var storageKey = 'prema_booking_location_draft';
    function readFields() {
        var fields = {};
        form.querySelectorAll('[name]').forEach(function(el) {
            if (el.name === 'csrf_token') return;
            if (el.type === 'checkbox') fields[el.name] = el.checked ? '1' : '0';
            else fields[el.name] = el.value;
        });
        return fields;
    }
    function rowCount(prefix) {
        return form.querySelectorAll(prefix + '-stop-row').length;
    }
    function restoreRows(prefix, addButtonId, fieldPrefix, keyPrefix) {
        var fields = (window.draft && window.draft.fields) || {};
        var count = 0;
        Object.keys(fields).forEach(function(name) {
            var m = name.match(new RegExp('^' + fieldPrefix + '_(\\d+)$'));
            if (m) count = Math.max(count, parseInt(m[1], 10));
        });
        var add = document.getElementById(addButtonId);
        while (rowCount(prefix) < count && add) add.click();
        form.querySelectorAll(prefix + '-stop-row').forEach(function(row, i) {
            var n = i + 1;
            var sel = row.querySelector('select');
            var keyEl = row.querySelector('.' + (prefix === '.pickup' ? 'pickup' : 'delivery') + '-stop-key');
            if (sel && fields[fieldPrefix + '_' + n] !== undefined) sel.value = fields[fieldPrefix + '_' + n];
            if (keyEl && fields[keyPrefix + '_' + n]) {
                keyEl.value = fields[keyPrefix + '_' + n];
                row.dataset.stopKey = keyEl.value;
            }
            if (sel) sel.dispatchEvent(new Event('change'));
        });
    }
    function restoreDraft() {
        var raw;
        try { raw = sessionStorage.getItem(storageKey); } catch (e) { return; }
        if (!raw) return;
        try { window.draft = JSON.parse(raw); } catch (e) { return; }
        if (!window.draft || window.draft.stage !== 'step1') return;
        if (Date.now() - (window.draft.saved_at || 0) > 30 * 60 * 1000) return;
        var fields = window.draft.fields || {};
        restoreRows('.pickup', 'add_pickup_stop_btn', 'pickup_saved_location_id', 'pickup_stop_key');
        restoreRows('.delivery', 'add_delivery_stop_btn', 'delivery_saved_location_id', 'delivery_stop_key');
        form.querySelectorAll('[name]').forEach(function(el) {
            if (el.name === 'csrf_token' || fields[el.name] === undefined) return;
            if (el.type === 'checkbox') el.checked = fields[el.name] === '1';
            else if (!/^((pickup|delivery)_saved_location_id_|(pickup|delivery)_stop_key_)/.test(el.name)) el.value = fields[el.name];
        });
        var params = new URLSearchParams(window.location.search);
        var newId = params.get('new_loc_id');
        var newType = params.get('new_loc_type') || '';
        var target = params.get('return_stop_key') || window.draft.return_stop_key || '';
        if (newId) form.querySelectorAll('.pickup-stop-row, .delivery-stop-row').forEach(function(row) {
            var key = (row.dataset.stopKey || (row.querySelector('.pickup-stop-key, .delivery-stop-key') || {}).value || '');
            var isPickup = row.classList.contains('pickup-stop-row');
            if (key === target && ((isPickup && (newType === 'pickup' || newType === 'both')) ||
                (!isPickup && (newType === 'delivery' || newType === 'both')))) row.querySelector('select').value = newId;
        });
        try { sessionStorage.removeItem(storageKey); } catch (e) {}
    }
    function leaveForLocation(link, event) {
        event.preventDefault();
        var row = link.closest('.pickup-stop-row, .delivery-stop-row');
        var keyEl = row && row.querySelector('.pickup-stop-key, .delivery-stop-key');
        var type = row && row.classList.contains('pickup-stop-row') ? 'pickup' : 'delivery';
        var draft = {stage: 'step1', saved_at: Date.now(),
            origin_url: window.location.pathname + window.location.search,
            return_stop_key: keyEl ? keyEl.value : '', fields: readFields()};
        try { sessionStorage.setItem(storageKey, JSON.stringify(draft)); } catch (e) {}
        var target = new URL(link.href, window.location.href);
        target.searchParams.set('type', type);
        target.searchParams.set('return', 'booking');
        target.searchParams.set('return_stop_key', draft.return_stop_key);
        target.searchParams.set('return_url', draft.origin_url);
        window.location.assign(target.href);
    }
    form.addEventListener('click', function(event) {
        var link = event.target.closest('.add-loc-link');
        if (link) leaveForLocation(link, event);
    });
    restoreDraft();
});

form.script:
function updatePortalTempLive() {
    var input = document.getElementById('portal_required_temperature_input');
    var unit = document.getElementById('portal_temperature_unit');
    var dual = document.getElementById('portal_temperature_dual');
    if (!input || !unit || !dual) { return; }
    if (input.value === '') {
        dual.textContent = 'Required for Reefer. 0°C / 32°F is valid.';
        return;
    }
    var num = parseFloat(input.value);
    if (isNaN(num)) { return; }
    var other = unit.value === 'c' ? (num * 9 / 5 + 32) : ((num - 32) * 5 / 9);
    var shown = Math.round(other * 10) / 10;
    dual.textContent = unit.value === 'c'
        ? input.value + '°C = ' + shown + '°F'
        : input.value + '°F = ' + shown + '°C';
}
function togglePortalTemperature() {
    var select = document.getElementById('portal_temperature_mode');
    var row = document.getElementById('portal_required_temperature');
    var input = document.getElementById('portal_required_temperature_input');
    var unit = document.getElementById('portal_temperature_unit');
    var reefer = select && select.value === 'reefer';
    if (row) { row.style.display = reefer ? '' : 'none'; }
    if (input) {
        input.required = reefer;
        if (reefer) {
            // Default 15°C when Reefer is selected and value is empty
            // (0°C is a valid explicit entry and is preserved).
            if (!input.value) { input.value = '15'; }
            updatePortalTempLive();
        } else {
            // Never submit a stale temperature with a Dry booking
            input.value = '';
            if (unit) { unit.value = 'c'; }
            updatePortalTempLive();
        }
    }
}
function onPortalShipmentTypeChange() {
    var select = document.getElementById('portal_shipment_type');
    var note = document.getElementById('portal_ftl_note');
    if (note) {
        note.style.display = select && select.value === 'ftl' ? '' : 'none';
    }
    // Re-evaluate the calendar under the new shipment
    // type: FTL only ever shows dedicated direct dates,
    // never feeder/transit cards.
    if (typeof fetchEligibleDates === 'function') {
        fetchEligibleDates();
    }
}

div.div:
Manual Quote Required — this pickup is outside
the scheduled booking network. Dates are not available here;
please request a manual quote.

template.script:
document.addEventListener('DOMContentLoaded', function() {
    // ════════════════════════════════════════════════════════════
    // Total shipment weight has one automatic mode (physical pallets
    // × configured default) and one explicit manual mode. Focus is
    // not an edit; only an actual value change enters manual mode.
    // ════════════════════════════════════════════════════════════
    var palletsEl = document.getElementById('pallets_input');
    var weightEl = document.getElementById('weight_input');
    var weightHint = document.getElementById('weight_hint');
    var resetLink = document.getElementById('reset_weight_link');
    var totalWeightModeInput = document.getElementById('total_weight_mode');
    var totalWeightMode = totalWeightModeInput && totalWeightModeInput.value === 'manual' ? 'manual' : 'auto';
    var WEIGHT_PER_PALLET = 500;  // initial fallback; updated from the corridor config via the capacity endpoint

    function autoWeight() {
        if (totalWeightMode === 'auto' && palletsEl && weightEl) {
            var p = parseInt(palletsEl.value) || 1;
            weightEl.value = Math.round(p * WEIGHT_PER_PALLET * 10) / 10;
            if (weightHint) { weightHint.style.display = 'none'; }
        }
        if (typeof syncPalletAllocationWeights === 'function') {
            syncPalletAllocationWeights();
        }
    }
    // Exposed for the stepper and capacity-refresh paths so the
    // weight always tracks pallet changes (programmatic writes do
    // not fire 'input' events).
    function syncCalculatedWeight() { autoWeight(); }
    if (palletsEl && weightEl) { syncCalculatedWeight(); }  // initial load
    if (palletsEl && weightEl) {
        palletsEl.addEventListener('input', function() { autoWeight(); fetchEligibleDates(); });
        weightEl.addEventListener('input', function() {
            totalWeightMode = 'manual';
            if (totalWeightModeInput) { totalWeightModeInput.value = 'manual'; }
            if (weightHint) { weightHint.style.display = ''; }
            if (typeof syncPalletAllocationWeights === 'function') {
                syncPalletAllocationWeights();
            }
            fetchEligibleDates();
        });
        if (resetLink) {
            resetLink.addEventListener('click', function(e) {
                e.preventDefault();
                if (typeof resetPalletWeights === 'function') { resetPalletWeights(); }
            });
        }
    }

    // ════════════════════════════════════════════════════════════
    // Date helpers
    // ════════════════════════════════════════════════════════════
    var DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
    var DAYS_SHORT = ['SUN','MON','TUE','WED','THU','FRI','SAT'];
    var MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
    var MONTHS_SHORT = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

    function fmtDisplay(ds) {
        var d = new Date(ds + 'T00:00:00');
        return DAYS[d.getDay()] + ', ' + MONTHS[d.getMonth()] + ' ' + d.getDate() + ', ' + d.getFullYear();
    }
    function fmtCardDate(ds) {
        var d = new Date(ds + 'T00:00:00');
        return {day: DAYS_SHORT[d.getDay()], date: MONTHS_SHORT[d.getMonth()].toUpperCase() + ' ' + d.getDate()};
    }
    function ymd(d) {
        return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
    }

    // ════════════════════════════════════════════════════════════
    // State
    // ════════════════════════════════════════════════════════════
    var hiddenDate = document.getElementById('requested_pickup_date');
    var displayEl = document.getElementById('selected_date_display');
    var cardsDiv = document.getElementById('pickup_date_cards');
    var viewMore = document.getElementById('view_more_dates');
    var calExpanded = document.getElementById('pickup_calendar_expanded');
    var calBody = document.getElementById('pickup_calendar_body');
    var legendDiv = document.getElementById('pickup_calendar_legend');
    var allDates = [];      // full eligible dates from backend
    var dateMap = {};       // date_str → metadata
    var calendarMonth = null; // {year, month} for the expanded calendar

    // ════════════════════════════════════════════════════════════
    // Select a date — single source of truth
    // ════════════════════════════════════════════════════════════
    function selectDate(ds) {
        if (!ds || !dateMap[ds]) return;
        hiddenDate.value = ds;
        // Bind the quote to the EXACT scheduled departure this date
        // resolves to — the server re-validates it (corridor, date,
        // active, status) before pricing.
        var depInput = document.getElementById('pickup_departure_id');
        if (depInput) { depInput.value = dateMap[ds].departure_id || ''; }
        displayEl.textContent = fmtDisplay(ds);
        renderCards();
        if (calExpanded.style.display !== 'none') renderCalendarGrid();
        refreshPalletCapacity();
    }

    // ════════════════════════════════════════════════════════════
    // Dynamic pallet capacity (canonical VehicleCapacityService,
    // segment-aware — Task M)
    //
    // The endpoint returns generic state (available /
    // can_fit_requested_quantity) plus ONE number:
    // max_selectable_pallets — the maximum this route + departure
    // can fit (truck max minus committed occupancy on the EXACT
    // segments the route overlaps; FTL needs the whole truck).
    // That number exists ONLY to clamp the stepper: the + button
    // stops at it and manual entry above it is clamped with a
    // generic message. It is NEVER rendered as text — no "9
    // pallets remaining", no "13 total", no "4 booked". The
    // SERVER (Get Price pre-check + confirmation lock) stays the
    // authoritative capacity gate.
    // ════════════════════════════════════════════════════════════
    var departureAvailable = false;
    var palletMax = 0;   // server-computed segment-aware max (internal)
    var palletsInput = document.getElementById('pallets_input');
    var capacityHint = document.getElementById('pallets_capacity_hint');
    var capacityError = document.getElementById('pallets_capacity_error');
    var getPriceBtn = document.querySelector('button[type="submit"]');

    function showCapacityError(msg) {
        capacityError.textContent = msg;
        capacityError.style.display = msg ? '' : 'none';
    }

    function generalizedRouteStopsParam() {
        var routeEl = document.getElementById('initial_route_stops_data');
        var raw = routeEl ? routeEl.textContent || '' : '';
        try {
            var stops = JSON.parse(raw);
            return Array.isArray(stops) && stops.length
                ? '&route_stops_json=' + encodeURIComponent(JSON.stringify(stops))
                : '';
        } catch (e) {
            return '';
        }
    }

    function setPlusDisabled() {
        var plus = document.getElementById('pallets_plus');
        if (plus) {
            plus.disabled = !departureAvailable ||
                (palletMax > 0 && (parseInt(palletsInput.value || '1', 10) || 1) >= palletMax);
        }
    }

    function applyPalletMax() {
        // Returns true when the entered quantity was clamped (the
        // caller then re-checks date eligibility at the clamped
        // quantity).
        if (departureAvailable && palletMax > 0) {
            palletsInput.min = 1;
            palletsInput.max = palletMax;
            var cur = parseInt(palletsInput.value || '1', 10);
            if (isNaN(cur) || cur < 1) { cur = 1; palletsInput.value = 1; }
            var clamped = false;
            if (cur > palletMax) {
                // Above the allowed quantity: clamp + generic
                // message — the exact number is internal.
                palletsInput.value = palletMax;
                clamped = true;
            }
            capacityHint.textContent = 'Enter the number of physical pallets/skids.';
            palletsInput.disabled = false;
            if (getPriceBtn) { getPriceBtn.disabled = false; }
            showCapacityError(clamped
                ? 'Selected quantity is not available on this departure.'
                : '');
            setPlusDisabled();
            syncCalculatedWeight();
            if (typeof buildPalletAllocations === 'function') { buildPalletAllocations(); }
            return clamped;
        } else {
            palletsInput.value = '';
            palletsInput.max = '';
            palletsInput.disabled = true;
            if (getPriceBtn) { getPriceBtn.disabled = true; }
            var plus = document.getElementById('pallets_plus');
            if (plus) { plus.disabled = true; }
            capacityHint.textContent = 'This departure is fully booked. Please choose another pickup date.';
            showCapacityError('');
            return false;
        }
    }

    function refreshPalletCapacity() {
        var date = hiddenDate.value;
        var puLat = parseFloat(document.querySelector('input[name="pickup_lat"]')?.value || 0);
        var puLng = parseFloat(document.querySelector('input[name="pickup_lng"]')?.value || 0);
        if (!date) return;
        capacityHint.textContent = 'Checking capacity…';
        var params = 'pickup_date=' + encodeURIComponent(date) +
            '&pickup_lat=' + puLat + '&pickup_lng=' + puLng +
            '&pallets=' + (parseInt(palletsInput?.value || '1', 10) || 1);
        params += generalizedRouteStopsParam();
        var pickupLocIds = [];
        document.querySelectorAll('input[name^="pickup_loc_id_"]').forEach(function(inp) {
            if (inp.value && pickupLocIds.indexOf(inp.value) === -1) pickupLocIds.push(inp.value);
        });
        var puLocId = (document.querySelector('input[name="pickup_loc_id"]') || {}).value || pickupLocIds[0] || '';
        var puFsa = (document.querySelector('input[name="pickup_fsa"]') || {}).value || '';
        var depInput = document.getElementById('pickup_departure_id');
        if (depInput && depInput.value) { params += '&departure_id=' + encodeURIComponent(depInput.value); }
        if (puLocId) { params += '&pickup_loc_id=' + encodeURIComponent(puLocId); }
        if (pickupLocIds.length) { params += '&pickup_loc_ids=' + encodeURIComponent(pickupLocIds.join(',')); }
        if (puFsa) { params += '&pickup_fsa=' + encodeURIComponent(puFsa); }
        // Segment-aware occupancy needs BOTH route ends + the
        // shipment type (same values fetchEligibleDates uses).
        var deLat = parseFloat(document.querySelector('input[name="delivery_lat"]')?.value || 0);
        var deLng = parseFloat(document.querySelector('input[name="delivery_lng"]')?.value || 0);
        var stSel = document.getElementById('portal_shipment_type');
        var st = (stSel && stSel.value === 'ftl') ? 'ftl' : 'ltl';
        params += '&delivery_lat=' + deLat + '&delivery_lng=' + deLng + '&shipment_type=' + st;
        var deliveryLocIds = [];
        document.querySelectorAll('.delivery-stop-breakdown-row input[name^="delivery_loc_id_"]').forEach(function(inp) {
            if (inp.value && deliveryLocIds.indexOf(inp.value) === -1) { deliveryLocIds.push(inp.value); }
        });
        var singleDel = document.querySelector('input[name="delivery_loc_id_1"]');
        if (!deliveryLocIds.length && singleDel && singleDel.value) { deliveryLocIds.push(singleDel.value); }
        if (deliveryLocIds.length) { params += '&delivery_loc_ids=' + encodeURIComponent(deliveryLocIds.join(',')); }
        fetch('/my/booking/capacity?' + params, {credentials: 'same-origin'})
            .then(function(r) { return r.json(); })
            .then(function(data) {
                if (data && data.available) {
                    departureAvailable = true;
                    palletMax = parseInt(data.max_selectable_pallets || '0', 10) || 0;
                    if (data.can_fit_requested_quantity === false) {
                        showCapacityError('Selected quantity is not available on this departure.');
                    } else {
                        showCapacityError('');
                    }
                } else {
                    departureAvailable = false;   // no service on this date
                    palletMax = 0;
                }
                if (data && data.per_pallet_weight) {
                    WEIGHT_PER_PALLET = data.per_pallet_weight;
                }
                if (resetLink) {
                    resetLink.textContent = 'Reset to ' + WEIGHT_PER_PALLET + ' lb/pallet';
                }
                var clamped = applyPalletMax();
                syncCalculatedWeight();
                if (clamped) {
                    // Quantity was pushed above this departure's
                    // capacity: re-check date eligibility at the
                    // clamped quantity (§6) — never silently
                    // accept the over-capacity entry.
                    fetchEligibleDates();
                }
            })
            .catch(function() {
                departureAvailable = false;
                palletMax = 0;
                capacityHint.textContent = 'Could not check capacity. Please try again.';
            });
    }

    function stepPallets(delta) {
        if (palletsInput.disabled) return;
        var cur = parseInt(palletsInput.value || '1', 10);
        if (isNaN(cur)) { cur = 1; }
        var next = cur + delta;
        if (next < 1) { next = 1; }
        if (palletMax > 0 && next > palletMax) {
            // The + button simply stops at the allowed quantity —
            // the number is never disclosed.
            showCapacityError('Selected quantity is not available on this departure.');
            return;
        }
        palletsInput.value = next;
        showCapacityError('');
        setPlusDisabled();
        syncCalculatedWeight();
        if (typeof buildPalletAllocations === 'function') { buildPalletAllocations(); }
    }

    function validatePalletInput() {
        if (palletsInput.disabled) return true;
        var raw = palletsInput.value;
        var cur = parseInt(raw, 10);
        if (raw === '' || isNaN(cur) || cur < 1) {
            showCapacityError('Please enter a valid pallet quantity (1 or more).');
            return false;
        }
        if (palletMax > 0 && cur > palletMax) {
            // Manual typing above the allowed quantity: clamp and
            // give the generic message — never the number.
            palletsInput.value = palletMax;
            showCapacityError('Selected quantity is not available on this departure.');
            syncCalculatedWeight();
            if (typeof buildPalletAllocations === 'function') { buildPalletAllocations(); }
            fetchEligibleDates();
            return false;
        }
        showCapacityError('');
        setPlusDisabled();
        return true;
    }
    if (palletsInput) {
        palletsInput.addEventListener('blur', validatePalletInput);
        palletsInput.addEventListener('input', function() {
            showCapacityError('');
        });
        palletsInput.addEventListener('wheel', function(ev) {
            ev.preventDefault();
        });
    }
    if (palletsInput) {
        var palletForm = palletsInput.closest('form');
        if (palletForm) {
            palletForm.addEventListener('submit', function(ev) {
                if (!validatePalletInput()) { ev.preventDefault(); }
            });
        }
    }
    // Stepper buttons: bound listeners instead of inline onclick, so
    // the control never depends on global function resolution.
    (function bindStepperButtons() {
        var plus = document.getElementById('pallets_plus');
        var minus = document.getElementById('pallets_minus');
        if (plus) { plus.addEventListener('click', function() { stepPallets(1); }); }
        if (minus) { minus.addEventListener('click', function() { stepPallets(-1); }); }
    })();

    // ════════════════════════════════════════════════════════════
    // Fetch eligible dates from backend
    // ════════════════════════════════════════════════════════════
    function fetchEligibleDates() {
        var puLat = parseFloat(document.querySelector('input[name="pickup_lat"]')?.value || 0);
        var puLng = parseFloat(document.querySelector('input[name="pickup_lng"]')?.value || 0);
        var deLat = parseFloat(document.querySelector('input[name="delivery_lat"]')?.value || 0);
        var deLng = parseFloat(document.querySelector('input[name="delivery_lng"]')?.value || 0);

        // The COMPLETE stop list: pickup + EVERY delivery saved
        // location. The backend evaluates the whole route — all
        // delivery stops, pallet count, capacity, equipment — never
        // just the first delivery.
        var pickupLocIds = [];
        document.querySelectorAll('input[name^="pickup_loc_id_"]').forEach(function(inp) {
            if (inp.value && pickupLocIds.indexOf(inp.value) === -1) pickupLocIds.push(inp.value);
        });
        var puLocId = (document.querySelector('input[name="pickup_loc_id"]') || {}).value || pickupLocIds[0] || '';
        var deliveryLocIds = [];
        document.querySelectorAll('.delivery-stop-breakdown-row input[name^="delivery_loc_id_"]').forEach(function(inp) {
            if (inp.value && deliveryLocIds.indexOf(inp.value) === -1) { deliveryLocIds.push(inp.value); }
        });
        var singleDel = document.querySelector('input[name="delivery_loc_id_1"]');
        if (!deliveryLocIds.length && singleDel && singleDel.value) { deliveryLocIds.push(singleDel.value); }

        if ((!puLat && !puLocId) || (!deLat && !deliveryLocIds.length)) {
            cardsDiv.innerHTML = '<div class="col-12 text-muted py-2">Select pickup and delivery locations to see available dates.</div>';
            return;
        }
        cardsDiv.innerHTML = '<div class="col-12 text-muted py-2"><div class="spinner-border spinner-border-sm me-2" role="status"/>Loading…</div>';

        var tempMode = document.getElementById('portal_temperature_mode');
        var equip = (tempMode && tempMode.value === 'reefer') ? 'reefer' : 'dry';
        // The customer's explicit Shipment Type selection is the
        // calendar authority — never inferred from pallet count.
        var stSel = document.getElementById('portal_shipment_type');
        var st = (stSel && stSel.value === 'ftl') ? 'ftl' : 'ltl';
        var params = 'pickup_lat=' + puLat + '&pickup_lng=' + puLng +
            '&delivery_lat=' + deLat + '&delivery_lng=' + deLng +
            '&pallets=' + (parseInt(palletsEl?.value) || 1) +
            '&weight_lbs=' + (parseFloat(weightEl?.value) || 500) +
            '&equipment=' + equip +
            '&shipment_type=' + st;
        params += generalizedRouteStopsParam();
        if (puLocId && deliveryLocIds.length) {
            params += '&pickup_loc_id=' + encodeURIComponent(puLocId) +
                '&pickup_loc_ids=' + encodeURIComponent(pickupLocIds.join(',')) +
                '&delivery_loc_ids=' + encodeURIComponent(deliveryLocIds.join(','));
        }

        fetch('/my/booking/eligible-dates?' + params, {credentials: 'same-origin'})
            .then(function(r) { return r.json(); })
            .then(function(data) {
                var banner = document.getElementById('manual_quote_banner');
                var depInput = document.getElementById('pickup_departure_id');
                if (data && data.manual_quote) {
                    // ONE eligibility authority: the same strict
                    // verdict Get Price uses. No fake dates.
                    allDates = [];
                    dateMap = {};
                    hiddenDate.value = '';
                    if (depInput) { depInput.value = ''; }
                    displayEl.textContent = '';
                    viewMore.style.display = 'none';
                    legendDiv.style.display = 'none';
                    calExpanded.style.display = 'none';
                    if (banner) {
                        // FTL gets its lane-level reason in the
                        // banner itself — never the generic
                        // network wording.
                        if (data.reason && data.reason.indexOf('Dedicated Full Truckload') !== -1) {
                            banner.innerHTML = '<strong>Manual Quote Required</strong> — ' + data.reason;
                        }
                        banner.classList.remove('d-none');
                    }
                    cardsDiv.innerHTML = '<div class="col-12 text-muted py-2">' +
                        (data.reason || 'Manual Quote Required') + '</div>';
                    return;
                }
                if (banner) { banner.classList.add('d-none'); }
                allDates = data.dates || [];
                if (st === 'ftl') {
                    // FTL is a dedicated direct movement: never
                    // render a feeder/transit card (defense in
                    // depth — the server already filters).
                    allDates = allDates.filter(function(d) { return !d.transfer; });
                }
                dateMap = {};
                allDates.forEach(function(d) { dateMap[d.date] = d; });
                // Auto-select earliest if nothing selected or selected date no longer valid
                if (allDates.length > 0 && (!hiddenDate.value || !dateMap[hiddenDate.value])) {
                    hiddenDate.value = allDates[0].date;
                    if (depInput) { depInput.value = dateMap[hiddenDate.value].departure_id || ''; }
                }
                renderCards();
                if (calExpanded.style.display !== 'none') renderCalendarGrid();
                refreshPalletCapacity();
            })
            .catch(function() {
                cardsDiv.innerHTML = '<div class="col-12 text-danger py-2">Could not load availability. Please try again.</div>';
            });
    }

    // ════════════════════════════════════════════════════════════
    // Render date cards (primary UI)
    // ════════════════════════════════════════════════════════════
    function renderCards() {
        if (allDates.length === 0) {
            cardsDiv.innerHTML = '<div class="col-12 text-muted py-2">No eligible pickup dates found for this movement.</div>';
            viewMore.style.display = 'none';
            displayEl.textContent = '';
            return;
        }

        var sel = hiddenDate.value;
        if (sel && dateMap[sel]) {
            displayEl.textContent = fmtDisplay(sel);
        }

        // Show first 4 dates as cards
        var show = allDates.slice(0, 4);
        var html = '';
        show.forEach(function(d) {
            var cd = fmtCardDate(d.date);
            var isSel = (d.date === sel);
            // Real service timing from the backend (corridor stop
            // config + identified travel-calc fallback) — never
            // invented here.
            var puTime = d.pickup_time || '';
            var dlDs = (d.delivery_date || d.estimated_delivery || '');
            var dlCd = dlDs ? fmtCardDate(dlDs) : null;
            var dlLine = dlCd ? dlCd.day + ' ' + dlCd.date : 'Delivery ETA TBD';
            if (d.delivery_time) { dlLine += ' · ' + d.delivery_time; }
            var puLabel = 'Estimated Pickup: ' + (puTime || 'Time TBD');
            var dlLabel = 'Estimated Delivery: ' + dlLine;
            var via = (d.transfer && d.transfer_hub_name)
                ? '<small class="d-block" style="font-size:10px;opacity:.85">Via ' + d.transfer_hub_name + '</small>'
                : '';
            // Generic only — exact pallet counts are never disclosed.
            var cap = (d.capacity_state !== 'full') ? 'Space available' : 'Sold out';

            if (isSel) {
                html += '<div class="col-6 col-md-3">' +
                    '<button type="button" class="card w-100 border-0 text-white p-2 date-card-selected" style="background:#C62828;cursor:pointer" data-date="' + d.date + '">' +
                    '<small style="font-size:10px;opacity:.9">✓ SELECTED</small>' +
                    '<div style="font-size:14px;font-weight:800;line-height:1.2">' + cd.day + '</div>' +
                    '<div style="font-size:16px;font-weight:700;line-height:1.2">' + cd.date + '</div>' +
                    '<small class="d-block" style="font-size:10px;opacity:.9">' + puLabel + '</small>' +
                    '<small class="d-block" style="font-size:10px;opacity:.9">' + dlLabel + '</small>' +
                    via +
                    '<small class="d-block" style="font-size:10px;opacity:.85">' + cap + '</small>' +
                    '</button></div>';
            } else {
                html += '<div class="col-6 col-md-3">' +
                    '<button type="button" class="card w-100 border p-2 date-card" style="cursor:pointer;transition:border-color .15s" data-date="' + d.date + '">' +
                    '<div style="font-size:14px;font-weight:800;color:#555;line-height:1.2">' + cd.day + '</div>' +
                    '<div style="font-size:16px;font-weight:700;line-height:1.2">' + cd.date + '</div>' +
                    '<small class="d-block" style="font-size:10px;color:#888">' + puLabel + '</small>' +
                    '<small class="d-block" style="font-size:10px;color:#888">' + dlLabel + '</small>' +
                    via +
                    '<small class="d-block" style="font-size:10px;color:#888">' + cap + '</small>' +
                    '</button></div>';
            }
        });
        cardsDiv.innerHTML = html;
        viewMore.style.display = allDates.length > 4 ? '' : 'none';

        // Bind card clicks
        cardsDiv.querySelectorAll('button[data-date]').forEach(function(btn) {
            btn.addEventListener('click', function() {
                selectDate(btn.getAttribute('data-date'));
            });
        });
    }

    // ════════════════════════════════════════════════════════════
    // Expanded calendar grid (secondary)
    // ════════════════════════════════════════════════════════════
    function renderCalendarGrid() {
        if (!calBody || allDates.length === 0) return;

        // Determine month to show
        var refDate;
        if (hiddenDate.value && dateMap[hiddenDate.value]) {
            refDate = new Date(hiddenDate.value + 'T00:00:00');
        } else {
            refDate = new Date(allDates[0].date + 'T00:00:00');
        }
        calendarMonth = {year: refDate.getFullYear(), month: refDate.getMonth()};

        function drawMonth() {
            var y = calendarMonth.year, m = calendarMonth.month;
            var first = new Date(y, m, 1);
            var last = new Date(y, m + 1, 0);
            var startDay = first.getDay(); // 0=Sun
            var totalDays = last.getDate();
            var today = new Date(); today.setHours(0,0,0,0);
            // Normalized YYYY-MM-DD comparison — never let a
            // datetime value or timezone drift break the highlight.
            var sel = String(hiddenDate.value || '').slice(0, 10);

            var h = '';
            // Header with nav arrows
            h += '<div class="d-flex justify-content-between align-items-center mb-2 px-1">';
            h += '<button type="button" class="btn btn-sm btn-outline-secondary cal-nav-prev" ' + (m === new Date().getMonth() && y === new Date().getFullYear() ? 'disabled' : '') + '>‹</button>';
            h += '<strong style="font-size:15px">' + MONTHS[m] + ' ' + y + '</strong>';
            h += '<button type="button" class="btn btn-sm btn-outline-secondary cal-nav-next">›</button>';
            h += '</div>';

            // Day headers
            h += '<div class="row row-cols-7 g-0 text-center mb-1" style="font-size:11px;color:#999;font-weight:600">';
            ['SUN','MON','TUE','WED','THU','FRI','SAT'].forEach(function(dh) { h += '<div class="col">' + dh + '</div>'; });
            h += '</div>';

            // Weeks
            var day = 1;
            for (var w = 0; w < 6 && day <= totalDays; w++) {
                h += '<div class="row row-cols-7 g-0">';
                for (var d = 0; d < 7; d++) {
                    if ((w === 0 && d < startDay) || day > totalDays) {
                        h += '<div class="col" style="min-height:40px"/>';
                    } else {
                        var ds = y + '-' + String(m+1).padStart(2,'0') + '-' + String(day).padStart(2,'0');
                        var cellDate = new Date(y, m, day);
                        var isPast = cellDate < today;
                        var isEligible = !!dateMap[ds];
                        var isSelected = (ds === sel);
                        var cellStyle = '';
                        var cellCls = '';
                        var dot = '';
                        var disabled = '';

                        if (isSelected) {
                            cellStyle = 'background:#C62828;color:#fff;border-radius:50%;width:36px;height:36px;line-height:36px;margin:0 auto;font-weight:700';
                        } else if (isEligible) {
                            cellStyle = 'font-weight:700;color:#111';
                            dot = '<span style="display:block;width:5px;height:5px;border-radius:50%;background:#C62828;margin:1px auto 0"/>';
                        } else if (isPast) {
                            cellStyle = 'color:#ccc';
                            disabled = 'disabled tabindex="-1"';
                        } else {
                            cellStyle = 'color:#bbb';
                            disabled = 'disabled tabindex="-1"';
                        }

                        h += '<div class="col d-flex flex-column align-items-center justify-content-center" style="min-height:40px">';
                        h += '<button type="button" class="border-0 bg-transparent p-0 text-center cal-cell' + (isEligible ? ' cal-eligible' : '') + '"' +
                            ' style="font-size:13px;' + cellStyle + '"' +
                            ' data-date="' + ds + '" ' + disabled + '>' + day + dot + '</button>';
                        h += '</div>';
                        day++;
                    }
                }
                h += '</div>';
            }
            calBody.innerHTML = h;
            legendDiv.style.display = '';

            // Bind cell clicks
            calBody.querySelectorAll('button.cal-eligible').forEach(function(btn) {
                btn.addEventListener('click', function() {
                    selectDate(btn.getAttribute('data-date'));
                });
            });

            // Bind nav
            calBody.querySelector('.cal-nav-prev')?.addEventListener('click', function(e) { e.preventDefault(); calendarMonth.month--; if (calendarMonth.month < 0) { calendarMonth.year--; calendarMonth.month = 11; } drawMonth(); });
            calBody.querySelector('.cal-nav-next')?.addEventListener('click', function(e) { e.preventDefault(); calendarMonth.month++; if (calendarMonth.month > 11) { calendarMonth.year++; calendarMonth.month = 0; } drawMonth(); });
        }
        drawMonth();
    }

    // ════════════════════════════════════════════════════════════
    // View More toggle
    // ════════════════════════════════════════════════════════════
    if (viewMore) {
        viewMore.addEventListener('click', function(e) {
            e.preventDefault();
            if (calExpanded.style.display === 'none') {
                calExpanded.style.display = '';
                viewMore.textContent = 'Hide Calendar ▴';
                renderCalendarGrid();
            } else {
                calExpanded.style.display = 'none';
                viewMore.textContent = 'View More Pickup Dates ▾';
            }
        });
    }

    // ════════════════════════════════════════════════════════════
    // Per-Pallet Allocation Engine
    // ════════════════════════════════════════════════════════════
    var deliveryStopCount = document.querySelectorAll('.delivery-stop-breakdown-row').length;
    var initialRouteStops = [];
    var savedLocationData = [];
    try { initialRouteStops = JSON.parse((document.getElementById('initial_route_stops_data') || {}).textContent || '[]'); } catch (e) {}
    try { savedLocationData = JSON.parse((document.getElementById('saved_locations_data') || {}).textContent || '[]'); } catch (e) {}
    var allocationState = {};
    var palletAllocBody = document.getElementById('pallet_allocation_body');
    var palletAllocSummary = document.getElementById('pallet_allocation_summary');
    var allocsJsonField = document.getElementById('pallet_allocations_json');
    var weightModeInput = document.getElementById('pallet_weight_mode');
    var allocationWeightMode = weightModeInput && weightModeInput.value === 'manual' ? 'manual' : 'auto';

    function roundPalletWeight(value) {
        return Math.round((Number(value) || 0) * 10) / 10;
    }
    function defaultPalletWeight(pallet, physical, totalWeight) {
        if (pallet < physical) {
            return roundPalletWeight(totalWeight / physical);
        }
        var prior = roundPalletWeight(totalWeight / physical) * (physical - 1);
        return roundPalletWeight(totalWeight - prior);
    }
    function updateWeightMode(mode) {
        allocationWeightMode = mode === 'manual' ? 'manual' : 'auto';
        if (weightModeInput) { weightModeInput.value = allocationWeightMode; }
    }

    function allocationPickupStops() {
        var stops = (initialRouteStops || []).filter(function(s) { return s.stop_type === 'pickup'; });
        if (stops.length) return stops;
        var first = document.querySelector('input[name="pickup_loc_id"]');
        return [{stop_key: 'PU1', stop_type: 'pickup', saved_location_id: first ? first.value : ''}];
    }
    function allocationDeliveryStops() {
        var stops = (initialRouteStops || []).filter(function(s) { return s.stop_type === 'delivery'; });
        if (stops.length) return stops;
        var rows = document.querySelectorAll('.delivery-stop-breakdown-row');
        rows.forEach(function(row, i) {
            var key = row.querySelector('.delivery-stop-key');
            stops.push({stop_key: key ? key.value : 'DL' + (i + 1), stop_type: 'delivery'});
        });
        if (!stops.length && document.querySelector('input[name="delivery_loc_id_1"]')) {
            stops.push({stop_key: 'DL1', stop_type: 'delivery'});
        }
        return stops;
    }
    function allocationLocationName(stop, fallback) {
        var id = String(stop.saved_location_id || '');
        var loc = savedLocationData.find(function(item) { return String(item.id) === id; });
        if (loc) return (loc.business_name || loc.name || loc.city || fallback) + (loc.city ? ' — ' + loc.city : '');
        return stop.location_name || stop.city || fallback;
    }
    function syncAllocationState() {
        document.querySelectorAll('.pallet-alloc-row').forEach(function(row) {
            var p = row.dataset.pallet;
            if (!allocationState[p]) allocationState[p] = {pickup: '', stops: [], weight: '', manualWeight: false, reference: ''};
            var pickup = row.querySelector('.pallet-pickup-select');
            var weight = row.querySelector('.pallet-weight');
            var reference = row.querySelector('.pallet-reference');
            if (pickup) allocationState[p].pickup = pickup.value;
            if (weight) allocationState[p].weight = weight.value;
            if (reference) allocationState[p].reference = reference.value;
            allocationState[p].stops = Array.from(row.querySelectorAll('.pallet-stop-check:checked')).map(function(cb) {
                return parseInt(cb.dataset.stop);
            });
        });
    }
    function allocationWeightTotal() {
        var total = 0;
        document.querySelectorAll('.pallet-alloc-row .pallet-weight').forEach(function(input) {
            total += parseFloat(input.value || 0) || 0;
        });
        return roundPalletWeight(total);
    }
    function applyAllocationWeights(physical, totalWeight) {
        var customPallets = [];
        for (var i = 1; i <= physical; i++) {
            var state = allocationState[String(i)];
            if (state && state.manualWeight) customPallets.push(i);
        }
        // Automatic mode always follows the configured per-pallet
        // default. A manually entered total is evenly distributed
        // unless individual pallet weights have been customized.
        if (allocationWeightMode === 'auto' || !customPallets.length) {
            for (var autoPallet = 1; autoPallet <= physical; autoPallet++) {
                allocationState[String(autoPallet)].weight = defaultPalletWeight(
                    autoPallet, physical, totalWeight);
            }
            return;
        }
        // Preserve custom rows and reconcile the remaining rows to
        // the edited total. The final non-custom row absorbs the
        // tenth-pound residual.
        var customTotal = 0;
        customPallets.forEach(function(pallet) {
            customTotal += parseFloat(allocationState[String(pallet)].weight || 0) || 0;
        });
        var remainingPallets = [];
        for (var remaining = 1; remaining <= physical; remaining++) {
            if (customPallets.indexOf(remaining) < 0) remainingPallets.push(remaining);
        }
        if (remainingPallets.length && totalWeight >= customTotal) {
            var remainingWeight = totalWeight - customTotal;
            remainingPallets.forEach(function(pallet, index) {
                if (index < remainingPallets.length - 1) {
                    allocationState[String(pallet)].weight = roundPalletWeight(
                        remainingWeight / remainingPallets.length);
                } else {
                    var prior = 0;
                    remainingPallets.slice(0, -1).forEach(function(priorPallet) {
                        prior += parseFloat(allocationState[String(priorPallet)].weight || 0) || 0;
                    });
                    allocationState[String(pallet)].weight = roundPalletWeight(
                        remainingWeight - prior);
                }
            });
        }
    }
    function seedAllocationState() {
        var movementStateEl = document.getElementById('submitted_booking_state_data');
        var submitted = {};
        try { submitted = JSON.parse(movementStateEl ? movementStateEl.textContent || '{}' : '{}'); } catch (e) {}
        var movements = [];
        try { movements = JSON.parse(submitted.pallet_movements_json || '[]'); } catch (e) {}
        (movements || []).forEach(function(item, i) {
            allocationState[String(i + 1)] = {
                pickup: item.pickup_stop_key || '',
                stops: (item.delivery_stop_keys || []).map(function(key) {
                    var index = allocationDeliveryStops().findIndex(function(stop) { return stop.stop_key === key; });
                    return index + 1;
                }).filter(function(index) { return index > 0; }),
                weight: item.weight_lbs || '',
                manualWeight: false,
                reference: item.reference || item.commodity || ''
            };
        });
        var allocs = [];
        try { allocs = JSON.parse(submitted.pallet_allocations_json || (allocsJsonField || {}).value || '[]'); } catch (e) {}
        (allocs || []).forEach(function(item) {
            var p = String(item.pallet);
            if (!allocationState[p]) allocationState[p] = {pickup: '', stops: [], weight: '', manualWeight: false, reference: ''};
            allocationState[p].stops = item.stops || [];
        });
    }
    function buildPalletAllocations() {
        var pickupStopsForAllocation = allocationPickupStops();
        var deliveryStopsForAllocation = allocationDeliveryStops();
        if (!palletAllocBody) return;
        syncAllocationState();
        var physInput = document.getElementById('pallets_input');
        var physical = parseInt(physInput ? physInput.value : '1') || 1;
        var totalWeight = parseFloat(weightEl ? weightEl.value : '0') || 0;
        for (var weightPallet = 1; weightPallet <= physical; weightPallet++) {
            var weightState = allocationState[String(weightPallet)];
            if (!weightState) {
                weightState = allocationState[String(weightPallet)] = {
                    pickup: '', stops: [], weight: '', manualWeight: false, reference: ''
                };
            }
        }
        applyAllocationWeights(physical, totalWeight);
        var html = '';
        for (var p = 1; p <= physical; p++) {
            var state = allocationState[String(p)] || {pickup: '', stops: [], weight: '', reference: ''};
            var pickupKey = state.pickup || (pickupStopsForAllocation.length === 1 ? pickupStopsForAllocation[0].stop_key : '');
            html += '<div class="d-flex align-items-center py-2 border-bottom pallet-alloc-row" data-pallet="' + p + '">';
            html += '<strong class="me-2" style="min-width:75px">PALLET ' + p + '</strong>';
            if (pickupStopsForAllocation.length > 1) {
                html += '<div class="me-2"><small class="text-muted">Pickup From</small><br/><select class="form-select form-select-sm pallet-pickup-select" data-pallet="' + p + '" onchange="updateAllocations()" style="min-width:175px">';
                html += '<option value="">— Select pickup —</option>';
                pickupStopsForAllocation.forEach(function(stop, i) {
                    html += '<option value="' + stop.stop_key + '"' + (pickupKey === stop.stop_key ? ' selected' : '') + '>' + allocationLocationName(stop, 'Pickup ' + (i + 1)) + '</option>';
                });
                html += '</select></div>';
            } else {
                html += '<div class="me-2"><small class="text-muted">Pickup</small><br/><span class="small">' + allocationLocationName(pickupStopsForAllocation[0], 'Pickup 1') + '</span></div>';
            }
            html += '<div class="me-2"><small class="text-muted">Weight (lb)</small><br/><input type="number" min="0" step="0.1" class="form-control form-control-sm pallet-weight" data-pallet="' + p + '" value="' + (state.weight || '') + '" style="width:90px"/></div>';
            html += '<div class="me-2"><small class="text-muted">Reference / PO</small><br/><input type="text" class="form-control form-control-sm pallet-reference" data-pallet="' + p + '" value="' + (state.reference || '') + '" style="width:140px"/></div>';
            html += '<div class="flex-grow-1"><small class="text-muted">Deliver To:</small><br/>';
            deliveryStopsForAllocation.forEach(function(stop, i) {
                var stopName = allocationLocationName(stop, 'Stop ' + (i + 1));
                if (deliveryStopsForAllocation.length === 1) {
                    html += '<span class="small me-2">' + stopName + '</span>';
                    html += '<input type="checkbox" class="pallet-stop-check" data-pallet="' + p + '" data-stop="1" data-stop-key="' + stop.stop_key + '" checked="checked" style="display:none"/>';
                } else {
                    html += '<label class="me-2" style="cursor:pointer;white-space:nowrap">';
                    html += '<input type="checkbox" class="pallet-stop-check" data-pallet="' + p + '" data-stop="' + (i + 1) + '" data-stop-key="' + stop.stop_key + '"' + (state.stops.indexOf(i + 1) >= 0 ? ' checked' : '') + ' onchange="updateAllocations()"/> ';
                    html += stopName.substring(0, 20) + (stopName.length > 20 ? '…' : '');
                    html += '</label>';
                }
            });
            html += '</div>';
            html += '<span class="badge rounded-pill ms-2 pallet-status-badge" data-pallet="' + p + '" style="min-width:90px;background:#6c757d;color:#fff">DEDICATED</span>';
            html += '</div>';
        }
        palletAllocBody.innerHTML = html;
        var placeholder = document.getElementById('pallet_alloc_placeholder');
        if (placeholder) placeholder.style.display = 'none';
        updateAllocations();
    }

    window.updateAllocations = function() {
        var pickupStopsForAllocation = allocationPickupStops();
        var deliveryStopsForAllocation = allocationDeliveryStops();
        syncAllocationState();
        var physInput = document.getElementById('pallets_input');
        var physical = parseInt(physInput ? physInput.value : '1') || 1;
        var allocs = [];
        for (var p = 1; p <= physical; p++) {
            var stops = [];
            document.querySelectorAll('.pallet-stop-check[data-pallet="' + p + '"]').forEach(function(cb) {
                if (cb.checked) stops.push(parseInt(cb.dataset.stop));
            });
            allocs.push({pallet: p, stops: stops, shared: stops.length > 1});
        }
        allocs.forEach(function(a) {
            var badge = document.querySelector('.pallet-status-badge[data-pallet="' + a.pallet + '"]');
            if (badge) {
                if (a.shared) { badge.textContent = 'SHARED — ' + a.stops.length + ' STOPS'; badge.style.background = '#7b1fa2'; badge.style.color = '#fff'; }
                else { badge.textContent = 'DEDICATED'; badge.style.background = '#6c757d'; badge.style.color = '#fff'; }
            }
        });
        for (var s = 1; s <= deliveryStopCount; s++) {
            var stopPallets = [];
            allocs.forEach(function(a) { if (a.stops.indexOf(s) >= 0) stopPallets.push(a.pallet); });
            var countBadge = document.getElementById('stop_pallet_badge_' + s);
            if (countBadge) countBadge.textContent = 'Pallets: ' + (stopPallets.length > 0 ? stopPallets.join(', ') : '—');
            var sharedBadge = document.getElementById('stop_shared_badge_' + s);
            if (sharedBadge) { sharedBadge.style.display = allocs.some(function(a) { return a.shared && a.stops.indexOf(s) >= 0; }) ? '' : 'none'; }
        }
        pickupStopsForAllocation.forEach(function(stop, index) {
            var pickupPallets = [];
            allocs.forEach(function(a) {
                var state = allocationState[String(a.pallet)] || {};
                var key = state.pickup || (pickupStopsForAllocation.length === 1 ? pickupStopsForAllocation[0].stop_key : '');
                if (key === stop.stop_key) pickupPallets.push(a.pallet);
            });
            var pickupBadge = document.getElementById('pickup_pallet_badge_' + (index + 1));
            if (pickupBadge) pickupBadge.textContent = 'Pallets: ' + (pickupPallets.length ? pickupPallets.join(', ') : '—');
        });
        if (allocsJsonField) allocsJsonField.value = JSON.stringify(allocs);
        var legacyEl = document.getElementById('legacy_pallets');
        if (legacyEl) legacyEl.value = physical;
        var modeInput = document.getElementById('shared_pallet_mode_input');
        if (modeInput) modeInput.value = allocs.some(function(a) { return a.shared; }) ? '1' : '0';
        if (palletAllocSummary) {
            var sc = allocs.filter(function(a) { return a.shared; }).length;
            var dc = allocs.filter(function(a) { return !a.shared; }).length;
            var parts = [physical + ' physical pallet' + (physical !== 1 ? 's' : '')];
            if (sc > 0) parts.push(sc + ' shared'); if (dc > 0) parts.push(dc + ' dedicated');
            palletAllocSummary.textContent = parts.join(' · ');
        }
        for (var s = 1; s <= deliveryStopCount; s++) {
            var sp = []; allocs.forEach(function(a) { if (a.stops.indexOf(s) >= 0) sp.push(a.pallet); });
            var hiddenInput = document.querySelector('input[name="delivery_pallets_' + s + '"]');
            if (hiddenInput) hiddenInput.value = sp.length || 1;
        }
    };

    window.syncPalletAllocationWeights = function() {
        if (!palletAllocBody) return;
        buildPalletAllocations();
    };
    window.resetPalletWeights = function() {
        updateWeightMode('auto');
        totalWeightMode = 'auto';
        if (totalWeightModeInput) { totalWeightModeInput.value = 'auto'; }
        autoWeight();
        if (weightHint) { weightHint.style.display = 'none'; }
        buildPalletAllocations();
    };

    if (palletAllocBody) {
        palletAllocBody.addEventListener('input', function(ev) {
            if (!ev.target.matches('.pallet-weight')) return;
            updateWeightMode('manual');
            totalWeightMode = 'manual';
            if (totalWeightModeInput) { totalWeightModeInput.value = 'manual'; }
            var p = ev.target.dataset.pallet;
            if (!allocationState[p]) allocationState[p] = {pickup: '', stops: [], weight: '', manualWeight: false, reference: ''};
            allocationState[p].manualWeight = true;
            allocationState[p].weight = ev.target.value;
            if (weightEl) { weightEl.value = allocationWeightTotal(); }
        });
    }

    var physPalletInput = document.getElementById('pallets_input');
    if (physPalletInput) {
        physPalletInput.addEventListener('input', function() { buildPalletAllocations(); autoWeight(); fetchEligibleDates(); });
    }
    seedAllocationState();
    buildPalletAllocations();
    window.buildPalletAllocations = buildPalletAllocations;

    // Initialize Reefer UI + FTL note on page load (not just on change)
    togglePortalTemperature();
    onPortalShipmentTypeChange();
    // Fetch on load
    fetchEligibleDates();
    var tempSelect = document.getElementById('portal_temperature_mode');
    if (tempSelect) tempSelect.addEventListener('change', fetchEligibleDates);

    // ════════════════════════════════════════════════════════════
    // Appointment Required Window
    // ════════════════════════════════════════════════════════════
    window.toggleAppointmentWindow = function() {
        var cb = document.getElementById('appointment_checkbox');
        var panel = document.getElementById('appointment_window');
        var timingType = document.querySelector('input[name="delivery_timing_type_1"]');
        if (cb && panel) {
            if (cb.checked) {
                panel.style.display = '';
                if (timingType) timingType.value = 'time_window';
                updateAppointmentInfo();
            } else {
                panel.style.display = 'none';
                if (timingType) timingType.value = 'flexible';
            }
        }
    };
    function updateAppointmentInfo() {
        var dateEl = document.getElementById('appt_delivery_date');
        var tzEl = document.getElementById('appt_timezone');
        var hoursEl = document.getElementById('appt_receiving_hours');
        // Use delivery location timezone from hidden field
        var tzField = document.querySelector('input[name="delivery_tz_1"]');
        var tz = tzField ? tzField.value : 'America/Toronto';
        // Friendly timezone label
        var tzMap = {'America/Toronto':'Eastern Time (ET)','America/Vancouver':'Pacific Time (PT)','America/Edmonton':'Mountain Time (MT)','America/Winnipeg':'Central Time (CT)','America/Chicago':'Central Time (CT)','America/New_York':'Eastern Time (ET)','America/Halifax':'Atlantic Time (AT)','America/St_Johns':'Newfoundland Time (NT)'};
        var tzFriendly = tzMap[tz] || tz;
        if (tzEl) tzEl.textContent = tzFriendly;
        if (hoursEl) hoursEl.textContent = 'Check with receiver'; // default if not configured
        // Estimate delivery date: pickup date + 1 day
        var hiddenDate = document.getElementById('requested_pickup_date');
        if (hiddenDate && hiddenDate.value) {
            var pd = new Date(hiddenDate.value + 'T00:00:00');
            pd.setDate(pd.getDate() + 1);
            var days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
            var months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
            if (dateEl) dateEl.textContent = days[pd.getDay()] + ', ' + months[pd.getMonth()] + ' ' + pd.getDate() + ', ' + pd.getFullYear();
        }
        updateTimeline();
    }
    function updateTimeline() {
        var from = document.getElementById('appt_from');
        var to = document.getElementById('appt_to');
        var fill = document.getElementById('appt_timeline_fill');
        var msg = document.getElementById('appt_validation_msg');
        if (!from || !to || !fill) return;
        var fv = from.value, tv = to.value;
        if (fv && tv) {
            var fmin = parseInt(fv.split(':')[0])*60 + parseInt(fv.split(':')[1]);
            var tmin = parseInt(tv.split(':')[0])*60 + parseInt(tv.split(':')[1]);
            if (fmin >= tmin) {
                if (msg) { msg.style.display = ''; msg.textContent = 'End time must be later than start time.'; }
                fill.style.width = '0';
            } else {
                if (msg) msg.style.display = 'none';
                var pctLeft = (fmin / 1440) * 100;
                var pctWidth = ((tmin - fmin) / 1440) * 100;
                fill.style.left = pctLeft + '%';
                fill.style.width = pctWidth + '%';
            }
        }
    }
    // Hook From/To inputs to update timeline
    var af = document.getElementById('appt_from'), at = document.getElementById('appt_to');
    if (af) af.addEventListener('input', updateTimeline);
    if (at) at.addEventListener('input', updateTimeline);
    // Hook pickup date change to update appointment date
    var pickupDateInput = document.getElementById('requested_pickup_date');
    if (pickupDateInput) {
        var origSelectDate = window.selectDate;
        if (typeof origSelectDate === 'function') {
            window.selectDate = function(ds) {
                origSelectDate(ds);
                if (document.getElementById('appointment_checkbox') && document.getElementById('appointment_checkbox').checked) {
                    updateAppointmentInfo();
                }
            };
        }
    }
});

document.addEventListener('DOMContentLoaded', function() {
    var SAVED_LOCS = [];
    try {
        var locsEl = document.getElementById('saved_locations_data');
        SAVED_LOCS = locsEl ? JSON.parse(locsEl.textContent || '[]') : [];
    } catch (e) { SAVED_LOCS = []; }

    var INITIAL_STOPS = [];
    try {
        var initialEl = document.getElementById('initial_route_stops_data');
        INITIAL_STOPS = initialEl ? JSON.parse(initialEl.textContent || '[]') : [];
    } catch (e) { INITIAL_STOPS = []; }

    var extraPickupCount = 0;
    var extraDeliveryCount = 0;
    var movementState = {pickups: {}, deliveries: {}, weights: {}, references: {}};

    function fmtHours(h) {
        if (!h) return 'Closed';
        var f = function(x) {
            var hh = Math.floor(x), mm = Math.round((x - hh) * 60);
            if (mm === 60) { hh += 1; mm = 0; }
            var ap = 'AM', hh12 = hh;
            if (hh >= 12) ap = 'PM';
            if (hh12 > 12) hh12 -= 12;
            if (hh12 === 0) hh12 = 12;
            return hh12 + ':' + (mm < 10 ? '0' : '') + mm + ' ' + ap;
        };
        return f(h[0]) + ' – ' + f(h[1]);
    }

    function hoursForDay(loc, dayIndex) {
        var locRec = null;
        for (var i = 0; i < SAVED_LOCS.length; i++) {
            if (SAVED_LOCS[i].id === loc) { locRec = SAVED_LOCS[i]; break; }
        }
        if (!locRec || !locRec.hours) return null;
        return locRec.hours[String(dayIndex)] || null;
    }

    function locOptions(selectedId, type) {
        var html = '<option value="">— Select saved location —</option>';
        SAVED_LOCS.forEach(function(l) {
            if (type && l.location_type !== type && l.location_type !== 'both') return;
            html += '<option value="' + l.id + '"' + (String(l.id) === String(selectedId) ? ' selected' : '') + '>'
                + (l.business_name || l.name) + ' (' + l.city + ')</option>';
        });
        return html;
    }

    function stopCardHtml(key, type, index) {
        var idp = key.replace(/[^a-zA-Z0-9]/g, '_');
        return '<div class="card mt-2 extra-stop-card" data-stop-key="' + key + '" data-stop-type="' + type + '">'
            + '<div class="card-body py-2">'
            + '<div class="d-flex justify-content-between align-items-center">'
            + '<strong>' + (type === 'pickup' ? 'PICKUP ' : 'DELIVERY ') + index + '</strong>'
            + '<button type="button" class="btn-close" onclick="removeStopCard(\'' + key + '\')" aria-label="Remove"></button>'
            + '</div>'
            + '<div class="row g-2 mt-1">'
            + '<div class="col-md-5"><small class="text-muted">Saved Location</small>'
            + '<select class="form-select form-select-sm stop-saved-location" id="' + idp + '_loc">' + locOptions('', type) + '</select></div>'
            + '<div class="col-md-7"><small class="text-muted">Facility Hours (today)</small><br/><span class="stop-hours-display small">—</span></div>'
            + '<div class="col-md-3"><label class="form-check form-check-inline"><input type="checkbox" class="form-check-input stop-liftgate"/> Liftgate</label></div>'
            + '<div class="col-md-3"><label class="form-check form-check-inline"><input type="checkbox" class="form-check-input stop-appointment"/> Appointment</label></div>'
            + '<div class="col-md-3"><select class="form-select form-select-sm stop-timing">'
            + '<option value="flexible">Flexible</option>'
            + '<option value="time_window">Time Window</option>'
            + '<option value="exact_appointment">Exact</option>'
            + '<option value="deadline">Deadline</option></select></div>'
            + '<div class="col-md-3"><input type="number" class="form-control form-control-sm stop-service-minutes" value="15" min="0" step="5"/> min svc</div>'
            + '<div class="col-md-6 stop-window-fields" style="display:none">'
            + '<input type="time" class="form-control form-control-sm d-inline-block stop-window-start" style="width:45%"/> — '
            + '<input type="time" class="form-control form-control-sm d-inline-block stop-window-end" style="width:45%"/></div>'
            + '<div class="col-md-12"><a href="/my/saved-locations/add?return=booking" class="btn btn-sm btn-outline-secondary add-loc-link">+ New Location</a></div>'
            + '<div class="col-md-12"><input type="text" class="form-control form-control-sm stop-instructions" placeholder="Stop instructions (dock, door, contact…)"/></div>'
            + '</div></div></div>';
    }

    window.addExtraPickupCard = function() {
        extraPickupCount += 1;
        // 'stp-pu-x…' — must NOT collide with the legacy main
        // pickup's 'stp-pu-1' (pickupStops()): a duplicate key would
        // break movement-pickup selection and payload resolution.
        var key = 'PUX' + extraPickupCount;
        var el = document.createElement('div');
        el.innerHTML = stopCardHtml(key, 'pickup', extraPickupCount + 1);
        document.getElementById('extra_pickup_cards').appendChild(el.firstChild);
        bindStopCard(key);
        refreshRouteSections();
        buildMovementGrid();
    };
    window.addExtraDeliveryCard = function() {
        extraDeliveryCount += 1;
        var key = 'DLX' + extraDeliveryCount;
        var el = document.createElement('div');
        el.innerHTML = stopCardHtml(key, 'delivery', extraDeliveryCount + 1);
        document.getElementById('extra_delivery_cards').appendChild(el.firstChild);
        bindStopCard(key);
        refreshRouteSections();
        buildMovementGrid();
    };

    function bindStopCard(key) {
        var card = document.querySelector('.extra-stop-card[data-stop-key="' + key + '"]');
        if (!card) return;
        var sel = card.querySelector('.stop-saved-location');
        var hoursDisp = card.querySelector('.stop-hours-display');
        var timing = card.querySelector('.stop-timing');
        var winFields = card.querySelector('.stop-window-fields');
        var update = function() {
            var locId = parseInt(sel.value);
            var today = new Date().getDay();
            var mapped = (today + 6) % 7; // JS Sun=0 → Odoo Mon=0
            var h = hoursForDay(locId, mapped);
            hoursDisp.textContent = fmtHours(h);
            hoursDisp.style.color = h ? '#198754' : '#dc3545';
        };
        sel.addEventListener('change', update);
        timing.addEventListener('change', function() {
            winFields.style.display = timing.value === 'flexible' ? 'none' : '';
        });
        update();
    }

    // Step 1 may already contain several pickups.  Materialize the
    // additional selected rows in the Step-2 builder so every
    // physical pallet can choose its source without losing the
    // stable PU key handed off by Step 1.
    (function seedInitialPickupCards() {
        var extra = INITIAL_STOPS.filter(function(s) { return s.stop_type === 'pickup'; }).slice(1);
        var host = document.getElementById('extra_pickup_cards');
        if (!host) return;
        extra.forEach(function(s, i) {
            var el = document.createElement('div');
            el.innerHTML = stopCardHtml(s.stop_key, 'pickup', i + 2);
            var card = el.firstChild;
            var select = card.querySelector('.stop-saved-location');
            if (select) select.value = String(s.saved_location_id || '');
            host.appendChild(card);
            bindStopCard(s.stop_key);
        });
    })();

    window.removeStopCard = function(key) {
        var card = document.querySelector('.extra-stop-card[data-stop-key="' + key + '"]');
        if (card) card.remove();
        refreshRouteSections();
        buildMovementGrid();
    };

    function pickupStops() {
        var selected = INITIAL_STOPS.filter(function(s) { return s.stop_type === 'pickup'; });
        if (!selected.length) {
            var first = document.querySelector('input[name="pickup_loc_id"]');
            selected = [{stop_key: 'PU1', type: 'pickup', legacy: true,
                saved_location_id: first ? first.value : ''}];
        }
        return selected.map(function(s, index) {
            return {key: s.stop_key || 'PU' + (index + 1), type: 'pickup',
                legacy: index === 0, saved_location_id: s.saved_location_id || '',
                card: null};
        });
    }
    function deliveryStops() {
        var stops = [];
        var rows = document.querySelectorAll('.delivery-stop-breakdown-row');
        rows.forEach(function(row, idx) {
            var keyInput = row.querySelector('.delivery-stop-key');
            stops.push({key: keyInput ? keyInput.value : ('DL' + (idx + 1)), type: 'delivery', legacy: true, index: idx + 1});
        });
        // Single-step-1 delivery (no visible row)
        var single = document.querySelector('input[name="delivery_loc_id_1"]');
        if (!rows.length && single) {
            var singleKey = document.querySelector('input[name="delivery_stop_key_1"]');
            stops.push({key: singleKey ? singleKey.value : 'DL1', type: 'delivery', legacy: true, index: 1});
        }
        document.querySelectorAll('#extra_delivery_cards .extra-stop-card').forEach(function(c) {
            stops.push({key: c.dataset.stopKey, type: 'delivery', legacy: false, card: c});
        });
        return stops;
    }

    function savedLocById(id) {
        if (!id) return null;
        for (var i = 0; i < SAVED_LOCS.length; i++) {
            if (String(SAVED_LOCS[i].id) === String(id)) { return SAVED_LOCS[i]; }
        }
        return null;
    }
    function locDisplayName(loc) {
        if (!loc) return '';
        var name = loc.business_name || loc.name || loc.city || '';
        var city = loc.city || '';
        if (name && city && name.toLowerCase().indexOf(city.toLowerCase()) === -1) {
            return name + ' — ' + city;
        }
        return name;
    }
    // The saved-location id behind a stop (legacy fields or card
    // selects) so the route chain can show real facility names —
    // never 'Pickup 1 → Pickup 1'.
    function stopSavedId(s) {
        if (s.legacy) {
            if (s.type === 'pickup') {
                var puLoc = document.querySelector('input[name="pickup_loc_id"]');
                return puLoc ? (parseInt(puLoc.value) || null) : null;
            }
            return legacyDeliveryLocId(s.index);
        }
        var sel = s.card ? s.card.querySelector('.stop-saved-location') : null;
        return sel ? (parseInt(sel.value) || null) : null;
    }
    function stopLabel(s, fallbackIndex) {
        var name = locDisplayName(savedLocById(stopSavedId(s)));
        if (name) return name;
        return (s.type === 'pickup' ? 'Pickup ' : 'Delivery ') + fallbackIndex;
    }

    function refreshRouteChain() {
        var parts = [];
        pickupStops().forEach(function(p, i) { parts.push(stopLabel(p, i + 1)); });
        deliveryStops().forEach(function(d, i) { parts.push(stopLabel(d, i + 1)); });
        var chain = parts.join(' → ');
        document.getElementById('route_stops_chain').textContent = chain;
        document.getElementById('route_summary_chain').textContent = chain;
    }

    // Display rules:
    //   A. 1 pickup + 1 delivery  → NO builder, NO route summary.
    //   B. 1 pickup + N deliveries → ROUTE SUMMARY (name chain).
    //   C. multiple pickups and/or shared pallets → stop details.
    function refreshRouteSections() {
        var builder = document.getElementById('stop_details_card');
        var summary = document.getElementById('route_summary_card');
        if (!builder || !summary) return;
        refreshRouteChain();
        var complex = builderActive();
        if (complex) {
            builder.style.display = '';
            summary.style.display = '';
            return;
        }
        var deCount = deliveryStops().length;
        if (deCount > 1) {
            summary.style.display = '';
            builder.style.display = 'none';
            return;
        }
        builder.style.display = 'none';
        summary.style.display = 'none';
    }

    function builderActive() {
        if (pickupStops().length > 1) return true;
        // A route with MULTIPLE delivery stops is a multi-stop milk
        // run even when no pallet is shared (1 pickup → A → B) —
        // the FTL/LTL engine must see EVERY ordered stop, so the
        // generalized route payload is always built for it.
        if (deliveryStops().length > 1) return true;
        // Shared pallet (multi-delivery) also generalizes the
        // booking. The per-pallet ALLOCATION engine is the live
        // UI; the legacy movement grid (whose rebuild wipes its
        // own checkboxes) is checked too for older pages.
        var shared = false;
        document.querySelectorAll('.pallet-stop-check:checked').forEach(function(cb) {
            var key = cb.dataset.pallet;
            var count = document.querySelectorAll('.pallet-stop-check:checked[data-pallet="' + key + '"]').length;
            if (count > 1) shared = true;
        });
        document.querySelectorAll('.movement-delivery-check:checked').forEach(function(cb) {
            var key = cb.dataset.palletKey;
            var count = document.querySelectorAll('.movement-delivery-check:checked[data-pallet-key="' + key + '"]').length;
            if (count > 1) shared = true;
        });
        return shared;
    }

    function buildMovementGrid() {
        var gridCard = document.getElementById('movement_grid_card');
        var body = document.getElementById('movement_grid_body');
        var physInput = document.getElementById('pallets_input');
        var physical = parseInt(physInput ? physInput.value : '1') || 1;
        var show = pickupStops().length > 1 || deliveryStops().length > 1 || extraPickupCount > 0;
        if (!body) return;
        if (!show) { if (gridCard) gridCard.style.display = 'none'; return; }
        if (gridCard) gridCard.style.display = '';
        // Re-rendering is used after pallet-count and checkbox
        // changes. Preserve selections by physical pallet key.
        document.querySelectorAll('.movement-row').forEach(function(row) {
            var p = row.dataset.pallet;
            var pu = row.querySelector('.movement-pickup');
            if (pu && pu.value) movementState.pickups[p] = pu.value;
            var wt = row.querySelector('.movement-weight');
            var ref = row.querySelector('.movement-reference');
            if (wt && wt.value) movementState.weights[p] = wt.value;
            if (ref) movementState.references[p] = ref.value;
            movementState.deliveries[p] = [];
            row.querySelectorAll('.movement-delivery-check:checked').forEach(function(cb) {
                movementState.deliveries[p].push(cb.dataset.stopKey);
            });
        });
        var html = '';
        for (var p = 1; p <= physical; p++) {
            html += '<div class="d-flex align-items-center py-2 border-bottom movement-row" data-pallet="' + p + '">';
            html += '<strong class="me-2" style="min-width:75px">PALLET ' + p + '</strong>';
            html += '<div class="me-3"><small class="text-muted">Pickup From</small><br/>';
            html += '<select class="form-select form-select-sm movement-pickup" data-pallet="' + p + '">';
            if (pickupStops().length > 1) html += '<option value="">— Select pickup —</option>';
            pickupStops().forEach(function(s, i) {
                var selected = movementState.pickups[p] === s.key ||
                    (!movementState.pickups[p] && pickupStops().length === 1 && i === 0);
                html += '<option value="' + s.key + '"' + (selected ? ' selected' : '') + '>' + stopLabel(s, i + 1) + '</option>';
            });
            html += '</select></div>';
            html += '<div class="me-3"><small class="text-muted">Weight (lb)</small><br/><input type="number" min="0" step="0.1" class="form-control form-control-sm movement-weight" data-pallet="' + p + '" value="' + (movementState.weights[p] || '') + '" style="width:105px"/></div>';
            html += '<div class="me-3"><small class="text-muted">Commodity / Reference</small><br/><input type="text" class="form-control form-control-sm movement-reference" data-pallet="' + p + '" value="' + (movementState.references[p] || '') + '" style="min-width:170px"/></div>';
            html += '<div class="flex-grow-1"><small class="text-muted">Deliver To</small><br/>';
            deliveryStops().forEach(function(s, i) {
                var checked = (movementState.deliveries[p] || []).indexOf(s.key) >= 0;
                html += '<label class="me-2" style="cursor:pointer;white-space:nowrap">';
                html += '<input type="checkbox" class="movement-delivery-check" data-pallet-key="pal-' + p + '" data-stop-key="' + s.key + '" data-delivery-index="' + (i + 1) + '"' + (checked ? ' checked' : '') + ' onchange="buildMovementGrid()"/> ';
                html += stopLabel(s, i + 1);
                html += '</label>';
            });
            html += '</div></div>';
        }
        body.innerHTML = html;
        refreshRouteSections();
    }
    // The dynamically-rendered assignment checkboxes use a small
    // inline onchange hook. Keep the implementation scoped here,
    // but expose only this handler for that browser event.
    window.buildMovementGrid = buildMovementGrid;

    function legacyDeliveryLocId(idx) {
        var el = document.querySelector('input[name="delivery_loc_id_' + idx + '"]');
        return el ? parseInt(el.value) || null : null;
    }
    function stopPayload(s) {
        if (s.type === 'pickup') {
            var puLoc = document.querySelector('input[name="pickup_loc_id"]');
            return {
                stop_key: s.key, stop_type: 'pickup',
                saved_location_id: parseInt(s.saved_location_id || (puLoc && puLoc.value)) || null,
                liftgate_required: !!(document.querySelector('input[name="liftgate_pickup"]') || {}).checked,
                appointment_required: !!(document.querySelector('input[name="appointment"]') || {}).checked,
                timing_type: 'flexible', service_time_minutes: 15, instructions: ''
            };
        }
        if (s.legacy) {
            var idx = s.index;
            var timingEl = document.querySelector('select[name="delivery_timing_type_' + idx + '"]');
            var wStart = document.querySelector('input[name="delivery_window_start_' + idx + '"]');
            var wEnd = document.querySelector('input[name="delivery_window_end_' + idx + '"]');
            return {
                stop_key: s.key, stop_type: 'delivery',
                saved_location_id: legacyDeliveryLocId(idx),
                liftgate_required: !!(document.querySelector('input[name="liftgate_delivery"]') || {}).checked,
                appointment_required: !!(document.querySelector('input[name="appointment"]') || {}).checked,
                timing_type: timingEl ? timingEl.value : 'flexible',
                window_start: wStart ? wStart.value : '',
                window_end: wEnd ? wEnd.value : '',
                service_time_minutes: 15, instructions: ''
            };
        }
        var c = s.card;
        var sel = c.querySelector('.stop-saved-location');
        var timing = c.querySelector('.stop-timing');
        return {
            stop_key: s.key, stop_type: s.type,
            saved_location_id: parseInt(sel.value) || null,
            liftgate_required: c.querySelector('.stop-liftgate').checked,
            appointment_required: c.querySelector('.stop-appointment').checked,
            timing_type: timing.value,
            window_start: c.querySelector('.stop-window-start').value,
            window_end: c.querySelector('.stop-window-end').value,
            service_time_minutes: parseInt(c.querySelector('.stop-service-minutes').value) || 15,
            instructions: c.querySelector('.stop-instructions').value
        };
    }

    var form = document.querySelector('form[action="/my/booking/quote"]');
    if (form) {
        var weightEl = document.getElementById('weight_input');
        form.addEventListener('submit', function(ev) {
            if (!builderActive()) {
                document.getElementById('route_stops_json').value = '';
                document.getElementById('pallet_movements_json').value = '';
                return;
            }
            var physical = parseInt((document.getElementById('pallets_input') || {}).value) || 1;
            var validation = document.getElementById('movement_validation_error');
            var allocationRows = document.querySelectorAll('.pallet-alloc-row');
            var pickupKeys = pickupStops().map(function(s) { return s.key; });
            function showMovementError(message) {
                ev.preventDefault();
                if (validation) { validation.textContent = message; validation.style.display = ''; }
            }
            allocationRows.forEach(function(row) { row.classList.remove('border-danger'); });
            if (allocationRows.length !== physical) {
                showMovementError('Please wait for all physical pallet assignments to load before getting a price.');
                return;
            }
            for (var rowIndex = 0; rowIndex < physical; rowIndex++) {
                var allocationRow = allocationRows[rowIndex];
                var pickupSelect = allocationRow.querySelector('.pallet-pickup-select');
                var selectedPickup = pickupSelect ? pickupSelect.value : (pickupKeys.length === 1 ? pickupKeys[0] : '');
                var selectedDeliveries = allocationRow.querySelectorAll('.pallet-stop-check:checked');
                var rowWeight = parseFloat((allocationRow.querySelector('.pallet-weight') || {}).value || 0) || 0;
                if (pickupKeys.indexOf(selectedPickup) < 0 || !selectedDeliveries.length || rowWeight <= 0) {
                    allocationRow.classList.add('border-danger');
                    showMovementError('Select a pickup and delivery for each pallet.');
                    return;
                }
            }
            var totalPalletWeight = 0;
            allocationRows.forEach(function(row) {
                var weightInput = row.querySelector('.pallet-weight');
                totalPalletWeight += parseFloat(weightInput && weightInput.value || 0) || 0;
            });
            var totalShipmentWeight = parseFloat(weightEl.value || 0) || 0;
            if (totalShipmentWeight <= 0 || Math.abs(totalPalletWeight - totalShipmentWeight) > 0.05) {
                showMovementError('Pallet weights must equal the total shipment weight.');
                return;
            }
            if (validation) { validation.textContent = ''; validation.style.display = 'none'; }
            // PALLET ALLOCATION is the sole live source for both
            // delivery allocations and canonical movement_v1 rows.
            var selByPallet = {};
            for (var p = 1; p <= physical; p++) {
                selByPallet[p] = [];
                document.querySelectorAll('.pallet-stop-check:checked[data-pallet="' + p + '"]').forEach(function(cb) {
                    selByPallet[p].push({stopKey: cb.dataset.stopKey || '', idx: parseInt(cb.dataset.stop)});
                });
            }
            var stops = pickupStops().concat(deliveryStops());
            function palletWeight(palletNumber) {
                var input = document.querySelector(
                    '.pallet-weight[data-pallet="' + palletNumber + '"]');
                return parseFloat(input && input.value || 0) || 0;
            }
            var routeStops = stops.map(function(s) {
                var payload = stopPayload(s);
                if (s.type === 'delivery') {
                    var count = 0;
                    var stopWeight = 0;
                    for (var p = 1; p <= physical; p++) {
                        if (selByPallet[p].some(function(m) { return m.stopKey === s.key; })) {
                            count++;
                            stopWeight += palletWeight(p) / selByPallet[p].length;
                        }
                    }
                    payload.pallets = count || 1;
                    payload.weight_lbs = stopWeight;
                } else {
                    var pickupCount = 0, pickupWeight = 0;
                    for (var pp = 1; pp <= physical; pp++) {
                        var pickup = document.querySelector('.pallet-pickup-select[data-pallet="' + pp + '"]');
                        var pickupValue = pickup ? pickup.value : (pickupKeys.length === 1 ? pickupKeys[0] : '');
                        if (pickupValue === s.key) {
                            pickupCount += 1;
                            pickupWeight += palletWeight(pp);
                        }
                    }
                    payload.pallets = pickupCount;
                    payload.weight_lbs = pickupWeight;
                }
                return payload;
            });
            var movements = [];
            var legacyAllocs = [];
            for (var p = 1; p <= physical; p++) {
                var puSelect = document.querySelector('.pallet-pickup-select[data-pallet="' + p + '"]');
                var pickupKey = puSelect ? puSelect.value : (pickupKeys.length === 1 ? pickupKeys[0] : '');
                var deliveryKeys = selByPallet[p].map(function(m) { return m.stopKey; });
                var deliveryIdx = selByPallet[p].map(function(m) { return m.idx; });
                var weightInput = document.querySelector('.pallet-weight[data-pallet="' + p + '"]');
                var refInput = document.querySelector('.pallet-reference[data-pallet="' + p + '"]');
                movements.push({
                    key: 'pal-' + p, label: 'Pallet-' + p,
                    weight_lbs: parseFloat(weightInput?.value || 0) || 0,
                    shared: deliveryKeys.length > 1,
                    pickup_stop_key: pickupKey, delivery_stop_keys: deliveryKeys,
                    commodity: refInput ? refInput.value : '', reference: refInput ? refInput.value : ''
                });
                legacyAllocs.push({pallet: p, stops: deliveryIdx, shared: deliveryKeys.length > 1});
            }
            document.getElementById('route_stops_json').value = JSON.stringify(routeStops);
            document.getElementById('pallet_movements_json').value = JSON.stringify(movements);
            document.getElementById('pallet_allocations_json').value = JSON.stringify(legacyAllocs);
        });
    }

    // The movement grid is part of the generalized route state. It
    // must exist as soon as Step 2 has multiple stops, and must
    // track every physical-pallet count change before submission.
    var movementPalletInput = document.getElementById('pallets_input');
    if (movementPalletInput) {
        movementPalletInput.addEventListener('input', buildMovementGrid);
        movementPalletInput.addEventListener('change', buildMovementGrid);
    }
    buildMovementGrid();

    // Restore a complete server-rendered validation state before
    // any second click. Generalized JSON remains visible and is
    // rebuilt into the same stable-key movement controls.
    function restoreSubmittedState() {
        var stateEl = document.getElementById('submitted_booking_state_data');
        if (!stateEl) return;
        var submitted;
        try { submitted = JSON.parse(stateEl.textContent || '{}'); } catch (e) { return; }
        if (!submitted || !submitted.pallet_movements_json) return;
        setNamedFields(submitted);
        var movementPayload;
        try { movementPayload = JSON.parse(submitted.pallet_movements_json || '[]'); } catch (e) { movementPayload = []; }
        movementState = {pickups: {}, deliveries: {}, weights: {}, references: {}};
        (movementPayload || []).forEach(function(item, i) {
            var p = String(i + 1);
            movementState.pickups[p] = item.pickup_stop_key || '';
            movementState.deliveries[p] = item.delivery_stop_keys || [];
            movementState.weights[p] = item.weight_lbs || '';
            movementState.references[p] = item.reference || item.commodity || '';
        });
        var palletInput = document.getElementById('pallets_input');
        if (palletInput) palletInput.dispatchEvent(new Event('input'));
        var weightInput = document.getElementById('weight_input');
        if (weightInput && submitted.weight_lbs !== undefined) weightInput.value = submitted.weight_lbs;
        buildMovementGrid();
        try {
            var allocs = JSON.parse(submitted.pallet_allocations_json || '[]');
            (allocs || []).forEach(function(item) {
                (item.stops || []).forEach(function(stop) {
                    var cb = document.querySelector('.pallet-stop-check[data-pallet="' + item.pallet + '"][data-stop="' + stop + '"]');
                    if (cb) cb.checked = true;
                });
            });
        } catch (e) {}
    }

    restoreSubmittedState();

    // ── Temporary booking draft while adding a location ────────
    // This is UX state only. The quote endpoint still validates all
    // customer-owned locations, stable keys, movements and capacity.
    var draftStorageKey = 'prema_booking_location_draft';
    function draftFields() {
        var out = {};
        form.querySelectorAll('[name]').forEach(function(el) {
            if (el.name === 'csrf_token') return;
            if (el.type === 'checkbox') out[el.name] = el.checked ? '1' : '0';
            else out[el.name] = el.value;
        });
        return out;
    }
    function captureDraft(link) {
        var row = link.closest('.extra-stop-card, .delivery-stop-breakdown-row');
        var key = row && (row.dataset.stopKey || (row.querySelector('.delivery-stop-key') || {}).value) || '';
        var type = row && row.classList.contains('extra-stop-card') ? row.dataset.stopType : 'delivery';
        var cards = [];
        document.querySelectorAll('.extra-stop-card').forEach(function(card) {
            var val = function(cls) { var el = card.querySelector(cls); return el ? el.value : ''; };
            var checked = function(cls) { var el = card.querySelector(cls); return !!(el && el.checked); };
            cards.push({key: card.dataset.stopKey, type: card.dataset.stopType,
                location: val('.stop-saved-location'), liftgate: checked('.stop-liftgate'),
                appointment: checked('.stop-appointment'), timing: val('.stop-timing'),
                service: val('.stop-service-minutes'), start: val('.stop-window-start'),
                end: val('.stop-window-end'), instructions: val('.stop-instructions')});
        });
        var movements = [];
        document.querySelectorAll('.pallet-alloc-row').forEach(function(mrow) {
            var p = mrow.dataset.pallet;
            var pu = mrow.querySelector('.pallet-pickup-select');
            var wt = mrow.querySelector('.pallet-weight');
            var ref = mrow.querySelector('.pallet-reference');
            movements.push({pallet: p, pickup: pu ? pu.value : (document.querySelector('.pickup-stop-summary-row') || {}).dataset?.stopKey || 'PU1',
                weight: wt ? wt.value : '', reference: ref ? ref.value : '', deliveries: Array.from(
                    mrow.querySelectorAll('.pallet-stop-check:checked')).map(function(cb) { return cb.dataset.stopKey; })});
        });
        var allocations = Array.from(document.querySelectorAll('.pallet-stop-check:checked')).map(function(cb) {
            return {pallet: cb.dataset.pallet, stop: cb.dataset.stop};
        });
        try {
            sessionStorage.setItem(draftStorageKey, JSON.stringify({stage: 'step2', saved_at: Date.now(),
                origin_url: window.location.pathname + window.location.search,
                return_stop_key: key, return_type: type, fields: draftFields(),
                cards: cards, movements: movements, allocations: allocations}));
        } catch (e) {}
    }
    function setNamedFields(fields) {
        if (!fields) return;
        form.querySelectorAll('[name]').forEach(function(el) {
            if (el.name === 'csrf_token' || fields[el.name] === undefined) return;
            if (el.type === 'checkbox') el.checked = fields[el.name] === '1';
            else el.value = fields[el.name];
        });
    }
    function restoreLocation(key, locationId) {
        if (!key || !locationId) return;
        var card = document.querySelector('.extra-stop-card[data-stop-key="' + key + '"]');
        if (card) {
            var sel = card.querySelector('.stop-saved-location');
            if (sel) { sel.value = String(locationId); sel.dispatchEvent(new Event('change')); }
            return;
        }
        var keyEl = Array.from(document.querySelectorAll('.delivery-stop-breakdown-row .delivery-stop-key')).find(function(el) { return el.value === key; });
        if (keyEl) {
            var loc = keyEl.closest('.delivery-stop-breakdown-row').querySelector('input[name^="delivery_loc_id_"]');
            if (loc) loc.value = String(locationId);
        }
    }
    function restoreDraft() {
        var raw;
        try { raw = sessionStorage.getItem(draftStorageKey); } catch (e) { return; }
        if (!raw) return;
        var saved;
        try { saved = JSON.parse(raw); } catch (e) { return; }
        if (!saved || saved.stage !== 'step2' || Date.now() - (saved.saved_at || 0) > 30 * 60 * 1000) return;
        setNamedFields(saved.fields);
        var wanted = saved.cards || [];
        wanted.forEach(function(item) {
            if (!document.querySelector('.extra-stop-card[data-stop-key="' + item.key + '"]')) {
                if (item.type === 'pickup') window.addExtraPickupCard();
                else window.addExtraDeliveryCard();
                var cards = document.querySelectorAll('.extra-stop-card');
                var card = cards[cards.length - 1];
                if (card) { card.dataset.stopKey = item.key; card.dataset.stopType = item.type; bindStopCard(item.key); }
            }
            var card = document.querySelector('.extra-stop-card[data-stop-key="' + item.key + '"]');
            if (!card) return;
            var set = function(cls, value) { var el = card.querySelector(cls); if (el && value !== undefined) el.value = value; };
            var check = function(cls, value) { var el = card.querySelector(cls); if (el) el.checked = !!value; };
            set('.stop-saved-location', item.location); check('.stop-liftgate', item.liftgate);
            check('.stop-appointment', item.appointment); set('.stop-timing', item.timing);
            set('.stop-service-minutes', item.service); set('.stop-window-start', item.start);
            set('.stop-window-end', item.end); set('.stop-instructions', item.instructions);
            var timing = card.querySelector('.stop-timing');
            if (timing) timing.dispatchEvent(new Event('change'));
        });
        movementState = {pickups: {}, deliveries: {}, weights: {}, references: {}};
        (saved.movements || []).forEach(function(item) {
            movementState.pickups[item.pallet] = item.pickup;
            movementState.deliveries[item.pallet] = item.deliveries || [];
            movementState.weights[item.pallet] = item.weight || '';
            movementState.references[item.pallet] = item.reference || '';
        });
        var palletInput = document.getElementById('pallets_input');
        if (palletInput) palletInput.dispatchEvent(new Event('input'));
        var weightInput = document.getElementById('weight_input');
        if (weightInput && saved.fields && saved.fields.weight_lbs !== undefined) {
            weightInput.value = saved.fields.weight_lbs;
        }
        (saved.movements || []).forEach(function(item) {
            var row = document.querySelector('.pallet-alloc-row[data-pallet="' + item.pallet + '"]');
            if (!row) return;
            var pu = row.querySelector('.pallet-pickup-select');
            var wt = row.querySelector('.pallet-weight');
            var ref = row.querySelector('.pallet-reference');
            if (pu) pu.value = item.pickup || pu.value;
            if (wt && item.weight !== undefined) wt.value = item.weight;
            if (ref && item.reference !== undefined) ref.value = item.reference;
            (item.deliveries || []).forEach(function(key) {
                var cb = row.querySelector('.pallet-stop-check[data-stop-key="' + key + '"]');
                if (cb) cb.checked = true;
            });
        });
        if (typeof window.updateAllocations === 'function') window.updateAllocations();
        var params = new URLSearchParams(window.location.search);
        restoreLocation(params.get('return_stop_key') || saved.return_stop_key, params.get('new_loc_id'));
        refreshRouteSections();
        try { sessionStorage.removeItem(draftStorageKey); } catch (e) {}
    }
    form.addEventListener('click', function(event) {
        var link = event.target.closest('.add-loc-link');
        if (!link) return;
        event.preventDefault();
        captureDraft(link);
        var row = link.closest('.extra-stop-card, .delivery-stop-breakdown-row');
        var key = row && (row.dataset.stopKey || (row.querySelector('.delivery-stop-key') || {}).value) || '';
        var type = row && row.classList.contains('extra-stop-card') ? row.dataset.stopType : 'delivery';
        var target = new URL(link.href, window.location.href);
        target.searchParams.set('type', type);
        target.searchParams.set('return', 'booking');
        target.searchParams.set('return_stop_key', key);
        target.searchParams.set('return_url', window.location.pathname + window.location.search);
        window.location.assign(target.href);
    });
    restoreDraft();
    refreshRouteSections();
});

div.script:
document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('.contact-toggle').forEach(function(link) {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            var targetId = this.getAttribute('data-target');
            var panel = document.getElementById(targetId);
            if (panel) {
                var isOpen = panel.style.display !== 'none';
                panel.style.display = isOpen ? 'none' : '';
                this.textContent = (isOpen ? 'CONTACT & INSTRUCTIONS ▾' : 'CONTACT & INSTRUCTIONS ▴');
            }
        });
    });
});
